  'pages' => 
  array (
    'home' => 
    array (
      'title' => 'Hospitality Academy: সৌদি আরবে হোটেল স্টাফ ট্রেনিং',
      'subtitle' => 'রিয়াদের Altus Advisory থেকে হোটেল টিমের জন্য ভূমিকাভিত্তিক ট্রেনিং, ব্যবহারিক মূল্যায়ন এবং যাচাইযোগ্য সার্টিফিকেশন। আরবি, ইংরেজি এবং আপনার কর্মীরা যে ভাষায় কথা বলেন সেই ভাষায়।',
      'body' => '<h2>Hospitality Academy কী?</h2><p>Hospitality Academy হলো সৌদি আরবের রিয়াদভিত্তিক হসপিটালিটি ও ব্যবসায়িক কৌশল প্রতিষ্ঠান Altus Advisory-র পাবলিক ট্রেনিং একাডেমি। এটি altus Hospitality Knowledge &amp; Performance প্ল্যাটফর্মে চলে, যা পদ অনুযায়ী হোটেল স্টাফ ট্রেনিং দেয় এবং তারপর যাচাই করে প্রত্যেকে আসলে কাজটি করতে পারেন কিনা।</p><h2>এটি সাধারণ অনলাইন কোর্স থেকে কীভাবে আলাদা?</h2><p>সম্পন্ন হওয়াকে প্রমাণ হিসেবে ধরা হয় না। প্রত্যেক শিক্ষার্থী ভূমিকাভিত্তিক শিক্ষা থেকে তাত্ত্বিক ও ব্যবহারিক মূল্যায়নে এগিয়ে যান, এবং ফলাফল নির্ধারিত দক্ষতার বিপরীতে রেকর্ড হয়। কোনো ফাঁক দেখা দিলে একটি অ্যাকশন প্ল্যান ও পুনর্মূল্যায়ন হয়, ফলে ম্যানেজাররা শেষ করা ভিডিওর তালিকা নয়, সক্ষমতার প্রমাণ দেখেন।</p><ol><li>পদের প্রয়োজনীয়তা অনুযায়ী নির্ধারিত শিক্ষা</li><li>একই স্ট্যান্ডার্ডে তাত্ত্বিক মূল্যায়ন ও ব্যবহারিক মূল্যায়ন</li><li>একটি দক্ষতার রেকর্ড, চিহ্নিত ফাঁক এবং একটি সংশোধনমূলক অ্যাকশন প্ল্যান</li><li>পুনর্মূল্যায়ন, একটি প্রস্তুতির স্ট্যাটাস এবং একটি যাচাইযোগ্য সার্টিফিকেট</li></ol><h2>একাডেমি কোন কোন হোটেল বিভাগ কভার করে?</h2><p>মাস্টার কারিকুলাম দশটি মূল পেশাগত ক্ষেত্রে সাজানো: হোটেলের মৌলিক বিষয়, ফ্রন্ট অফিস, হাউসকিপিং, ফুড অ্যান্ড বেভারেজ, কিচেন, সেলস ও মার্কেটিং, রেভিনিউ ও রিজার্ভেশন, অতিথি অভিজ্ঞতা, কোয়ালিটি ও অডিট, এবং সিকিউরিটি ও সেফটি। <a href="/en/courses">কোর্স ক্যাটালগ</a> দেখুন অথবা নির্দিষ্ট পদের জন্য একটি কাঠামোবদ্ধ <a href="/en/learning-paths">লার্নিং পাথ</a> অনুসরণ করুন।</p><h2>হোটেল কর্মীরা কোন ভাষায় শিখতে পারেন?</h2><p>আরবি ও ইংরেজি একটি অভিন্ন অভিজ্ঞতা হিসেবে যুক্ত, আরবি ডান থেকে বামে সাজানো। স্টাফ ওয়ার্কস্পেস হিন্দি, উর্দু, ফিলিপিনো, বাংলা, নেপালি ও মালয়ালমও সমর্থন করে, যাতে প্রতিটি শিফটে যারা স্ট্যান্ডার্ডটি বাস্তবায়ন করেন তারা তা বুঝতে পারেন।</p><h2>একজন নিয়োগকর্তা কি সার্টিফিকেট যাচাই করতে পারেন?</h2><p>হ্যাঁ। প্রতিটি সার্টিফিকেটে একটি অনন্য নম্বর ও একটি যাচাই কোড থাকে, এবং যে কেউ <a href="/en/verify">সার্টিফিকেট যাচাই পেজে</a> নিশ্চিত হতে পারেন এটি বৈধ, মেয়াদোত্তীর্ণ নাকি বাতিল।</p><h2>একাডেমি কীভাবে Vision 2030-কে সহায়তা করে?</h2><p>Vision 2030-এর লক্ষ্য 2030 সালের মধ্যে রাজ্যে বছরে 150 মিলিয়ন ভ্রমণ, এবং এটি সৌদি মানবসম্পদকে সেই প্রবৃদ্ধির কেন্দ্রে রাখে। Altus Advisory দ্বিভাষিক লার্নিং পাথ, মূল্যায়িত দক্ষতা এবং সৌদি আরব ও GCC-র হোটেলগুলো নির্ভর করতে পারে এমন সার্টিফিকেশনের মাধ্যমে একাডেমিকে সেই লক্ষ্যের সাথে সামঞ্জস্যপূর্ণ করে।</p><p>হোটেল মালিক ও অপারেটররা <a href="/en/hotels">তাদের প্রপার্টির জন্য ট্রেনিং চালু করতে পারেন</a> অথবা <a href="/en/contact">রিয়াদে একাডেমি টিমের সাথে কথা বলতে পারেন</a>।</p>',
      'cta_label' => 'কোর্স ক্যাটালগ দেখুন',
      'meta_title' => 'সৌদি আরবে হোটেল স্টাফ ট্রেনিং | Hospitality Academy',
      'meta_description' => 'Altus Advisory থেকে সৌদি আরবে হোটেল স্টাফ ট্রেনিং: আরবি ও ইংরেজিতে ভূমিকাভিত্তিক শিক্ষা, ব্যবহারিক মূল্যায়ন এবং যাচাইযোগ্য সার্টিফিকেট।',
