    'about' => 
    array (
      'title' => 'Hospitality Academy সম্পর্কে',
      'subtitle' => 'রিয়াদে Altus Advisory-র পাবলিক ট্রেনিং একাডেমি: কনটেন্টের পেছনে কারা, কীভাবে তা অনুমোদিত হয়, এবং আমরা কী দাবি করব ও কী করব না।',
      'body' => '<h2>Hospitality Academy কারা পরিচালনা করে?</h2><p>Hospitality Academy পরিচালনা করে Altus Advisory, সৌদি আরবের রিয়াদে সদর দপ্তরযুক্ত একটি বুটিক কৌশল প্রতিষ্ঠান, যা GCC ও MENA জুড়ে ক্লায়েন্টদের সেবা দেয়। Altus দুটি সমন্বিত বিভাগের মাধ্যমে কাজ করে, Hospitality Solutions এবং Business Growth Solutions, এবং একাডেমি হলো সেই মাধ্যম যার দ্বারা এর অপারেটিং স্ট্যান্ডার্ড সরাসরি হোটেল টিমের কাছে পৌঁছায়।</p><h2>ট্রেনিং কনটেন্ট কোন অভিজ্ঞতার ওপর ভিত্তি করে?</h2><p>কনটেন্টটি Altus প্রতিষ্ঠাতাদের অপারেটিং স্ট্যান্ডার্ড থেকে নেওয়া, যাদের সম্মিলিত নেতৃত্বের অভিজ্ঞতা 60 বছরের বেশি, যা Marriott, IHG, Starwood ও Accor সিস্টেমে এবং স্বতন্ত্র হোটেলে অর্জিত। ট্রেনিং কোনো সাধারণ কোর্স লাইব্রেরি থেকে নয়, শিফটে যেভাবে সম্পাদিত হয় সেভাবে স্ট্যান্ডার্ড অপারেটিং প্রসিডিউর থেকে শুরু হয়।</p><h2>একাডেমি altus প্ল্যাটফর্মের সাথে কীভাবে সম্পর্কিত?</h2><p>একাডেমি হলো altus Hospitality Knowledge &amp; Performance প্ল্যাটফর্মের পাবলিক প্রবেশপথ। প্ল্যাটফর্মের ভেতরে হোটেলগুলো পদ অনুযায়ী শিক্ষা নির্ধারণ করে, তাত্ত্বিক ও ব্যবহারিক মূল্যায়ন চালায়, দক্ষতার ফাঁক ও অ্যাকশন প্ল্যান ট্র্যাক করে, এবং প্রত্যেক কর্মীর প্রস্তুতি দেখে। একটি নিয়ন্ত্রিত AI সহকারী কেবল অনুমোদিত কনটেন্ট থেকে কর্মীদের প্রশ্নের উত্তর দেয়, এবং কনটেন্ট কোনো প্রশ্ন কভার না করলে তা জানিয়ে দেয়।</p><h2>ট্রেনিং কনটেন্ট কীভাবে অনুমোদিত হয়?</h2><p>প্রতিটি লেসন, প্রসিডিউর ও মূল্যায়ন শিক্ষার্থীরা দেখার আগে একটি নিয়ন্ত্রিত পর্যালোচনার মধ্য দিয়ে যায়।</p><ol><li>লেখক একটি খসড়া প্রস্তুত করেন।</li><li>খসড়াটি অভ্যন্তরীণ অনুমোদন পায়।</li><li>খসড়াটি কোয়ালিটি অনুমোদন পায়।</li><li>কনটেন্টটি প্রকাশিত হয় এবং এর সংস্করণ রেকর্ড হয়।</li></ol><p>লেখকরা নিজেদের কাজ অনুমোদন করতে পারেন না, এবং পূর্ববর্তী সংস্করণগুলো রেকর্ডে থাকে যাতে একজন অডিটর দেখতে পারেন যে কোনো তারিখে কোন স্ট্যান্ডার্ড প্রযোজ্য ছিল।</p><h2>কোন নীতিগুলো একাডেমিকে পরিচালিত করে?</h2><p>Altus Advisory প্রতিটি দায়িত্বে যে নীতিগুলো প্রয়োগ করে, একাডেমি সেগুলোই অনুসরণ করে।</p><ul><li>অনুমানের চেয়ে প্রমাণ: সক্ষমতা উপস্থিতি থেকে ধরে নেওয়া হয় না, মূল্যায়নের মাধ্যমে দেখানো হয়।</li><li>এমন স্ট্যান্ডার্ড যা প্রতিটি শিফটে টেকে, আরবি, ইংরেজি এবং হোটেল কর্মীদের ব্যবহৃত কর্মীবাহিনীর ভাষায়।</li><li>দায়িত্বের বাইরেও অংশীদারত্ব: কাজ শেষ হওয়ার পরও জ্ঞান ক্লায়েন্ট প্রতিষ্ঠানের ভেতরেই থাকে।</li><li>সৌদিকরণ ও যুব ক্ষমতায়নের জন্য Vision 2030-এর লক্ষ্যের সাথে সামঞ্জস্য রেখে সৌদি মানবসম্পদের প্রতি সহায়তা।</li></ul><h2>একাডেমি কী দাবি করে না?</h2><p>এই সাইট কোনো পাসের হার, ক্লায়েন্টের সমর্থন বা স্বীকৃতির দাবি প্রকাশ করে না। একটি সার্টিফিকেট ঠিক তা-ই বলে যা এটি রেকর্ড করে: কে কোন কোর্স বা প্রোগ্রাম সম্পন্ন করেছেন, কোন তারিখে, কী ফলাফলে, এবং এটি এখনো বৈধ কিনা। পড়ুন <a href="/en/certificates">সার্টিফিকেশন কীভাবে কাজ করে</a>, অথবা আরও জানুন <a href="/en/altus">Altus Advisory ও এর সেবা</a> সম্পর্কে।</p>',
