    'for-hotels' => 
    array (
      'title' => 'সৌদি আরবের প্রপার্টির জন্য হোটেল ট্রেনিং প্ল্যাটফর্ম',
      'subtitle' => 'পদ অনুযায়ী শিক্ষা নির্ধারণ, তত্ত্ব ও অনুশীলনের মূল্যায়ন, দক্ষতার ফাঁক পূরণ এবং প্রতিটি প্রপার্টির প্রস্তুতি দেখা, একটি দ্বিভাষিক ওয়ার্কস্পেসে।',
      'body' => '<h2>হোটেলগুলোর কেন শুধু কোর্স সম্পন্ন নয়, সক্ষমতার প্রমাণ দরকার?</h2><p>বেশিরভাগ হোটেল আগে থেকেই জানে তাদের টিমের কী করা উচিত। কঠিন বিষয় হলো প্রমাণ করা যে প্রত্যেকে বর্তমান স্ট্যান্ডার্ডে তা করতে পারেন, এবং একজন অতিথি, অডিট বা পরিদর্শনের আগেই ফাঁকগুলো খুঁজে পাওয়া। রিয়াদ ও সৌদি আরবজুড়ে হোটেলগুলোর জন্য সেই ফাঁক পূরণ করতে Altus Advisory তৈরি করেছে altus Hospitality Knowledge &amp; Performance প্ল্যাটফর্ম।</p><h2>প্ল্যাটফর্ম থেকে একটি হোটেল কী পায়?</h2><p>একটি একক ওয়ার্কস্পেস যেখানে প্রতিটি প্রপার্টির ট্রেনিং, মূল্যায়ন ও প্রমাণ একসাথে থাকে।</p><ul><li>ব্যক্তি, পদ, বিভাগ বা কোহর্টকে নির্ধারিত শিক্ষা, শেষ তারিখ ও অব্যাহতিসহ</li><li>ওজনযুক্ত রুব্রিকে স্কোর করা তাত্ত্বিক ও ব্যবহারিক মূল্যায়ন, যেখানে একটি গুরুত্বপূর্ণ মানদণ্ড ফলাফলের সর্বোচ্চ সীমা নির্ধারণ করে</li><li>দক্ষতার প্রোফাইল, একটি গ্যাপ হিটম্যাপ, প্রমাণ আপলোডসহ অ্যাকশন প্ল্যান এবং পুনর্মূল্যায়ন</li><li>প্রত্যেক কর্মীর প্রস্তুতির স্ট্যাটাস, প্রি-ওপেনিং টিমের জন্য ওপেনিং প্রস্তুতিসহ</li><li>কোয়ালিটি অডিট, KPI এবং CSV ও XLSX-এ এক্সপোর্ট করা রিপোর্ট</li><li>একটি নিয়ন্ত্রিত AI সহকারী যা কেবল আপনার অনুমোদিত SOP ও পলিসি থেকে, উদ্ধৃতিসহ উত্তর দেয়</li><li>প্রপার্টির ব্র্যান্ডিং: আপনার লোগো, রং ও নাম</li></ul><h2>প্ল্যাটফর্মের ভেতরে কে কী দেখেন?</h2><p>অ্যাক্সেস আপনার প্রতিষ্ঠানের কাঠামো অনুসরণ করে। একজন বিভাগীয় প্রধান তার টিম দেখেন, একজন জেনারেল ম্যানেজার প্রপার্টি দেখেন, এবং একজন নির্বাহী পোর্টফোলিওর সারসংক্ষেপ ও একটি প্রিন্টযোগ্য বোর্ড রিপোর্ট দেখেন। প্রতিটি ধাপ আপনার প্রতিষ্ঠানের মধ্যে সীমাবদ্ধ এবং একটি অডিট লগে রেকর্ড হয়, এবং কোনো প্রতিষ্ঠান অন্য প্রতিষ্ঠানের ডেটা দেখতে পারে না।</p><h2>প্ল্যাটফর্মটি কোন প্রপার্টির জন্য তৈরি?</h2><p>Altus Advisory-র কর্পোরেট প্রোফাইল অনুযায়ী, প্ল্যাটফর্মটি বিশেষভাবে সৌদি আরব ও আরব অঞ্চলজুড়ে স্বতন্ত্র হোটেল, সার্ভিসড অ্যাপার্টমেন্ট এবং SME প্রতিষ্ঠানের জন্য তৈরি, যাদের বৈশ্বিক চেইন সিস্টেমের খরচ ও জটিলতা ছাড়াই ব্যবহারিক, স্ট্যান্ডার্ডভিত্তিক ট্রেনিং প্রয়োজন। চাহিদা বাড়ছে: সৌদি পর্যটন মন্ত্রণালয়ের প্রাথমিক তথ্যে 2025 সালে 122 মিলিয়ন দেশীয় ও আন্তর্জাতিক ভ্রমণ রেকর্ড হয়েছে, এবং Vision 2030-এর লক্ষ্য 2030 সালের মধ্যে বছরে 150 মিলিয়ন ভ্রমণ।</p><h2>আমরা কীভাবে শুরু করব?</h2><p>সেটআপ শুরু হয় আপনার কাঠামো থেকে, খালি ক্যাটালগ থেকে নয়।</p><ol><li>আপনার প্রপার্টি, বিভাগ এবং প্রতি বিভাগে আনুমানিক কর্মীসংখ্যা জানান।</li><li>Altus প্রতিষ্ঠানটি সেট আপ করে এবং পদগুলোকে তাদের প্রয়োজনীয় দক্ষতার সাথে যুক্ত করে।</li><li>বাধ্যতামূলক ট্রেনিং নির্ধারণ করা হয়, ফলে কর্মীরা প্রথম লগইনেই নিজেদের তালিকা খোলেন।</li><li>ম্যানেজাররা তাদের ড্যাশবোর্ড থেকে সম্পন্ন, মূল্যায়নের ফলাফল ও প্রস্তুতি অনুসরণ করেন।</li></ol><p>দেখুন <a href="/en/hotels/training">বিভাগ অনুযায়ী ট্রেনিং প্রোগ্রাম</a>, ব্রাউজ করুন <a href="/en/programs">সার্টিফিকেশন প্রোগ্রাম</a>, অথবা <a href="/en/contact">একাডেমি টিমের সাথে কথা বলুন</a>।</p>',
