    'hotels-training' => 
    array (
      'title' => 'বিভাগ অনুযায়ী হোটেল স্টাফ ট্রেনিং প্রোগ্রাম',
      'subtitle' => 'প্রতিটি হোটেল বিভাগকে কী শেখানো হয়, কোন ক্রমে দেওয়া হয়, এবং একজন কর্মী তত্ত্বাবধান ছাড়া কাজ করার আগে সক্ষমতা কীভাবে নিশ্চিত করা হয়।',
      'body' => '<h2>প্রতিটি হোটেল বিভাগের কী ট্রেনিং প্রয়োজন?</h2><p>প্রতিটি বিভাগ মাস্টার কারিকুলামের মধ্যে নিজস্ব ট্র্যাক অনুসরণ করে, যা Altus Advisory রিয়াদে মাঠে পরীক্ষিত অপারেটিং স্ট্যান্ডার্ড থেকে তৈরি করেছে। কনটেন্ট সাজানো পেশাগত ক্ষেত্র, ট্র্যাক, মডিউল ও লেসন হিসেবে, এরপর মূল্যায়ন ও সার্টিফিকেশন, ফলে প্রতিটি পদের একটি নির্ধারিত পথ রয়েছে।</p><ul><li><strong>ফ্রন্ট অফিস:</strong> আগমন ও প্রস্থান, অতিথি রেজিস্ট্রেশন ও প্রাইভেসি, রুম অ্যাসাইনমেন্ট, অভিযোগ সামলানো, আপসেলিং এবং নাইট অডিট।</li><li><strong>হাউসকিপিং:</strong> রুম পরিষ্কারের ক্রম, বিছানা ও বাথরুমের স্ট্যান্ডার্ড, কেমিক্যাল সেফটি, লস্ট অ্যান্ড ফাউন্ড, লন্ড্রি, পাবলিক এরিয়া এবং পরিদর্শন।</li><li><strong>ফুড অ্যান্ড বেভারেজ:</strong> সার্ভিসের ক্রম, অভ্যর্থনা ও বসানো, টেবিল ও বেভারেজ সার্ভিস, ব্যাঙ্কুয়েট এবং পয়েন্ট অফ সেল প্রসিডিউর।</li><li><strong>কিচেন:</strong> খাদ্য নিরাপত্তা, তাপমাত্রা নিয়ন্ত্রণ, সংরক্ষণ ও গ্রহণ, অ্যালার্জেন ব্যবস্থাপনা, ছুরি ব্যবহারের নিরাপত্তা এবং অপচয় নিয়ন্ত্রণ।</li><li><strong>সেলস, রেভিনিউ ও রিজার্ভেশন:</strong> সেলস ও মার্কেটিং, রিজার্ভেশন প্রসিডিউর, ডিস্ট্রিবিউশন এবং রেভিনিউর মৌলিক বিষয়।</li><li><strong>অতিথি অভিজ্ঞতা, কোয়ালিটি ও অডিট:</strong> সার্ভিস রিকভারি, ব্র্যান্ড ও SOP মেনে চলা, এবং কোয়ালিটি পরিদর্শন।</li><li><strong>সিকিউরিটি ও সেফটি:</strong> প্রত্যেক কর্মীর জন্য ফায়ার সেফটি, জরুরি প্রতিক্রিয়া এবং সিকিউরিটি প্রসিডিউর।</li></ul><h2>হোটেল স্টাফ ট্রেনিং কোন ক্রমে দেওয়া হয়?</h2><p>প্রথমে সেফটি ও ভিত্তি, তারপর পদের দক্ষতা, তারপর একই স্ট্যান্ডার্ডের মূল্যায়ন।</p><ol><li>প্রত্যেক কর্মীর জন্য হোটেলের মৌলিক বিষয়, প্রপার্টি ইনডাকশন এবং সেফটি</li><li>পদের পূর্বশর্ত, যেমন হাউসকিপিংয়ে কেমিক্যাল সেফটি বা কিচেনে খাদ্য নিরাপত্তা ও অ্যালার্জেন ব্যবস্থাপনা</li><li>ভিডিও, PDF, স্লাইড বা অডিওতে সংক্ষিপ্ত ব্যবহারিক লেসনসহ পদের মডিউল</li><li>একটি তাত্ত্বিক মূল্যায়ন, তারপর একজন সুপারভাইজারের দ্বারা ব্যবহারিক মূল্যায়ন</li><li>একটি সার্টিফিকেট, অথবা ফাঁক পাওয়া গেলে একটি অ্যাকশন প্ল্যান ও পুনর্মূল্যায়ন</li></ol><h2>ট্রেনিং কি আমাদের নিজস্ব হোটেল স্ট্যান্ডার্ড অনুসরণ করতে পারে?</h2><p>হ্যাঁ। প্ল্যাটফর্মটি প্রতিটি প্রপার্টির জন্য হোয়াইট-লেবেল, এবং আপনার অনুমোদিত SOP, পলিসি ও চেকলিস্ট কারিকুলামের পাশাপাশি থাকে, প্রতিটি সংস্করণের বিপরীতে কর্মীদের স্বীকৃতি রেকর্ডসহ। AI সহকারী কেবল সেই অনুমোদিত কনটেন্ট থেকে কর্মীদের প্রশ্নের উত্তর দেয়।</p><h2>যারা আরবি বা ইংরেজি পড়েন না, তাদের জন্য কি ট্রেনিং পাওয়া যায়?</h2><p>লেসনগুলো আরবি ও ইংরেজিতে দ্বিভাষিক, এবং সৌদি আরবজুড়ে হোটেলে কাজ করা বহুজাতিক টিমের জন্য স্টাফ ওয়ার্কস্পেস হিন্দি, উর্দু, ফিলিপিনো, বাংলা, নেপালি ও মালয়ালমও সমর্থন করে।</p><p>দেখুন <a href="/en/courses">সম্পূর্ণ কোর্স ক্যাটালগ</a>, অনুসরণ করুন <a href="/en/learning-paths">পদ অনুযায়ী লার্নিং পাথ</a>, অথবা পড়ুন <a href="/en/hotels">হোটেলগুলো কীভাবে প্ল্যাটফর্মটি চালু করে</a>।</p>',
