    array (
      'title' => 'হোটেল ট্রেনিং সার্টিফিকেট ও যাচাই',
      'subtitle' => 'একটি Hospitality Academy সার্টিফিকেট কী রেকর্ড করে, কখন ইস্যু হয়, এবং একজন নিয়োগকর্তা কীভাবে কয়েক সেকেন্ডে যাচাই করতে পারেন এটি আসল ও হালনাগাদ কিনা।',
      'body' => '<h2>Hospitality Academy সার্টিফিকেট কখন ইস্যু হয়?</h2><p>একজন শিক্ষার্থী কোনো কোর্সের প্রতিটি বাধ্যতামূলক লেসন সম্পন্ন করলে এবং সেই কোর্সের নির্ধারিত পাস মার্ক বা তার বেশি পেয়ে মূল্যায়নে উত্তীর্ণ হলে সার্টিফিকেট ইস্যু হয়। প্রোগ্রামের প্রতিটি কোর্স সম্পন্ন হলে প্রোগ্রাম সার্টিফিকেট ইস্যু হয়। সার্টিফিকেশন উপস্থিতি নয়, মূল্যায়িত সক্ষমতা প্রতিফলিত করার জন্য তৈরি।</p><h2>একটি হোটেল ট্রেনিং সার্টিফিকেট কী রেকর্ড করে?</h2><p>প্রতিটি সার্টিফিকেট একজন নিয়োগকর্তার প্রয়োজনীয় তথ্য রেকর্ড করে, এর বেশি কিছু নয়।</p><ul><li>শিক্ষার্থীর নাম</li><li>সম্পন্ন কোর্স বা প্রোগ্রাম</li><li>সম্পন্নের তারিখ ও চূড়ান্ত স্কোর</li><li>একটি অনন্য সার্টিফিকেট নম্বর, একটি যাচাই কোড এবং একটি QR কোড</li><li>যেখানে বিষয়টির পর্যায়ক্রমিক রিফ্রেশ প্রয়োজন, যেমন সেফটি ও ফুড সেফটি, সেখানে মেয়াদ শেষের তারিখ</li></ul><h2>একটি হোটেল ট্রেনিং সার্টিফিকেট কীভাবে যাচাই করব?</h2><p>পাবলিক যাচাই পেজ ব্যবহার করুন। কোনো অ্যাকাউন্টের প্রয়োজন নেই।</p><ol><li><a href="/en/verify">সার্টিফিকেট যাচাই পেজ</a> খুলুন।</li><li>সার্টিফিকেটে ছাপা যাচাই কোডটি দিন, অথবা এর QR কোড স্ক্যান করুন।</li><li>ফেরত আসা স্ট্যাটাস পড়ুন: বৈধ, মেয়াদোত্তীর্ণ, বাতিল অথবা পাওয়া যায়নি।</li></ol><p>বৈধ ফলাফলে শিক্ষার্থীর নাম, বিষয় ও ইস্যুর তারিখ দেখায়, ব্যক্তি সম্পর্কে আর কিছু নয়।</p><h2>কেন একটি সার্টিফিকেট বাতিল দেখাতে পারে?</h2><p>ভুলবশত ইস্যু হলে, এর পেছনের মূল্যায়নের ফলাফল অবৈধ প্রমাণিত হলে, অথবা ইস্যুকারী প্রতিষ্ঠানের অনুরোধে সার্টিফিকেট বাতিল করা হয়। বাতিল সার্টিফিকেট অদৃশ্য হয় না, যাচাইযোগ্য থাকে এবং বাতিল স্ট্যাটাসই দেখাতে থাকে, যাতে আগের কোনো কপি হালনাগাদ হিসেবে উপস্থাপন করা না যায়।</p><h2>সার্টিফিকেট কারা ইস্যু করে?</h2><p>সার্টিফিকেট ইস্যু হয় altus Hospitality Knowledge &amp; Performance প্ল্যাটফর্মের মাধ্যমে, যা সৌদি আরবের রিয়াদে Altus Advisory পরিচালনা করে। একটি সার্টিফিকেট একটি নির্দিষ্ট তারিখে একজন নির্দিষ্ট ব্যক্তির একটি নির্দিষ্ট কোর্স বা প্রোগ্রাম সম্পন্ন করা রেকর্ড করে। এটি কোনো লাইসেন্স, নিয়ন্ত্রক অনুমোদন বা এমন বিবৃতি নয় যে ধারক কোনো নির্দিষ্ট পদের জন্য যোগ্য।</p><p>উপলব্ধ <a href="/en/programs">সার্টিফিকেশন প্রোগ্রাম</a> দেখুন অথবা আপনার হোটেল কর্মীদের সার্টিফিকেশন সম্পর্কে <a href="/en/contact">একাডেমি টিমকে জিজ্ঞাসা করুন</a>।</p>',
