      'title' => 'প্রাইভেসি পলিসি',
      'subtitle' => 'একাডেমি কী সংরক্ষণ করে, কেন করে, কে তা দেখতে পারে এবং কতদিন রাখা হয়।',
      'body' => '<h2>এই পলিসি কাদের জন্য প্রযোজ্য</h2><p>এই পলিসি প্রযোজ্য Hospitality Academy-র ক্ষেত্রে, যা সৌদি আরবের রিয়াদে Altus Advisory পরিচালিত ট্রেনিং একাডেমি, এবং সেই শিক্ষার্থীদের ক্ষেত্রে যারা তাদের নিয়োগকর্তার মাধ্যমে বা সরাসরি এটি ব্যবহার করেন।</p><h2>কী সংগ্রহ করা হয়</h2><p>একজন শিক্ষার্থীর জন্য একাডেমি সংরক্ষণ করে:</p><ul><li>নাম, কর্মক্ষেত্রের ইমেইল এবং দেওয়া হলে মোবাইল নম্বর</li><li>নিয়োগকর্তা, প্রপার্টি, বিভাগ ও পদ</li><li>লার্নিং রেকর্ড: এনরোলমেন্ট, লেসনের অগ্রগতি, মূল্যায়নের প্রচেষ্টা ও স্কোর, সার্টিফিকেট এবং প্রসিডিউর স্বীকৃতি</li></ul><h2>কেন সংগ্রহ করা হয়</h2><p>তথ্য ব্যবহার করা হয়:</p><ul><li>ট্রেনিং প্রদানে</li><li>ট্রেনিং সম্পন্ন হয়েছে কিনা রেকর্ড করতে</li><li>সার্টিফিকেট ইস্যু ও যাচাই করতে</li><li>একজন নিয়োগকর্তাকে তার নিজস্ব কর্মীবাহিনীর কমপ্লায়েন্স অবস্থা দেখাতে</li></ul><p>কিছুই বিক্রি করা হয় না, এবং কিছুই বিজ্ঞাপনের জন্য ব্যবহার করা হয় না।</p><h2>প্রসিডিউর স্বীকৃতি</h2><p>একটি স্বীকৃতি ব্যবহারকারী, প্রসিডিউরের সঠিক সংস্করণ, টাইমস্ট্যাম্প এবং উৎস নেটওয়ার্ক ঠিকানা রেকর্ড করে। এটি ইচ্ছাকৃত: যে স্বীকৃতি একজন ব্যক্তি, একটি সংস্করণ ও একটি মুহূর্তের সাথে যুক্ত করা যায় না, তা কোনো কিছুরই প্রমাণ নয়।</p><h2>কে একটি লার্নিং রেকর্ড দেখতে পারেন</h2><p>একটি লার্নিং রেকর্ড দেখতে পারেন:</p><ul><li>শিক্ষার্থী</li><li>শিক্ষার্থীর লাইন ম্যানেজার</li><li>একই প্রতিষ্ঠানের বিভাগ, প্রপার্টি ও প্রতিষ্ঠানের অ্যাডমিনিস্ট্রেটর</li><li>একজন একাডেমি অ্যাডমিনিস্ট্রেটর</li></ul><p>কোনো প্রতিষ্ঠান অন্য প্রতিষ্ঠানের ডেটা দেখতে পারে না।</p><h2>সংরক্ষণকাল</h2><p>অ্যাকাউন্ট সক্রিয় থাকা পর্যন্ত লার্নিং রেকর্ড ও সার্টিফিকেট সংরক্ষিত থাকে, এবং এরপর ইস্যুকারী প্রতিষ্ঠানের অডিটের জন্য যতদিন প্রয়োজন ততদিন। যাচাই চালু রাখতে সার্টিফিকেট রেকর্ড অনির্দিষ্টকাল সংরক্ষিত থাকে।</p><h2>আপনার অনুরোধ</h2><p>একজন শিক্ষার্থী তার নিয়োগকর্তার অ্যাডমিনিস্ট্রেটরের মাধ্যমে অথবা <a href="/en/contact">যোগাযোগ পেজের</a> মাধ্যমে সরাসরি একাডেমির সাথে যোগাযোগ করে তার রেকর্ডের একটি কপি বা সংশোধনের অনুরোধ করতে পারেন। <a href="/en/terms">ব্যবহারের শর্তাবলি</a> অ্যাকাউন্ট ও সার্টিফিকেটের নিয়ম নির্ধারণ করে।</p>',
      'cta_label' => 'একাডেমির সাথে যোগাযোগ করুন',
      'meta_title' => 'প্রাইভেসি পলিসি | Altus Advisory-র Hospitality Academy',
      'meta_description' => 'Hospitality Academy প্রাইভেসি পলিসি: শিক্ষার্থীর কী ডেটা সংগ্রহ করা হয়, কেন, কে লার্নিং রেকর্ড দেখতে পারেন, এবং রেকর্ড ও সার্টিফিকেট কতদিন রাখা হয়।',
      'focus_keyword' => 'প্রাইভেসি পলিসি',
