    'terms' => 
    array (
      'title' => 'ব্যবহারের শর্তাবলি',
      'subtitle' => 'একাডেমি ব্যবহার এবং এর ইস্যু করা সার্টিফিকেটের ক্ষেত্রে প্রযোজ্য শর্তাবলি।',
      'body' => '<h2>পরিধি</h2><p>এই শর্তাবলি প্রযোজ্য সৌদি আরবের রিয়াদে Altus Advisory পরিচালিত Hospitality Academy এবং এর মাধ্যমে ইস্যু করা সার্টিফিকেটের ক্ষেত্রে।</p><h2>অ্যাকাউন্ট</h2><p>একটি অ্যাকাউন্ট একজন নির্দিষ্ট ব্যক্তির।</p><ul><li>অ্যাকাউন্ট শেয়ার করার অনুমতি নেই।</li><li>অন্য কারও হয়ে ট্রেনিং সম্পন্ন করার অনুমতি নেই।</li></ul><p>যেকোনো একটি করলে তা থেকে পাওয়া সার্টিফিকেট অবৈধ হয় এবং অ্যাকাউন্ট স্থগিত করার কারণ হয়।</p><h2>মূল্যায়ন</h2><p>মূল্যায়নের প্রচেষ্টাগুলো একটি টাইমস্ট্যাম্প ও প্রচেষ্টা নম্বরসহ রেকর্ড হয়। প্রতিটি মূল্যায়নের জন্য কনফিগার করা অনুযায়ী প্রচেষ্টার সীমা, সময়সীমা এবং প্রশ্নের র‍্যান্ডমাইজেশন প্রয়োগ করা হয়। এসব নিয়ন্ত্রণ এড়িয়ে পাওয়া ফলাফল বাতিল।</p><h2>সার্টিফিকেট</h2><p>একটি সার্টিফিকেট একটি নির্দিষ্ট তারিখে একজন নির্দিষ্ট ব্যক্তির একটি নির্দিষ্ট কোর্স বা প্রোগ্রাম সম্পন্ন করা রেকর্ড করে। এটি কোনো লাইসেন্স, নিয়ন্ত্রক অনুমোদন বা এমন বিবৃতি নয় যে ধারক কোনো নির্দিষ্ট পদের জন্য যোগ্য। এমন যেকোনো ব্যবহার এই শর্তাবলির বাইরে। সার্টিফিকেটের স্ট্যাটাস <a href="/en/verify">যাচাই পেজে</a> দেখা যায়।</p><h2>কনটেন্ট</h2><p>একাডেমি প্রকাশিত কোর্সের উপকরণ ও প্রসিডিউর একাডেমির বা যে প্রতিষ্ঠান সেগুলো লিখেছে তার সম্পত্তি থাকে। কোনো প্রতিষ্ঠানের আপলোড করা প্রসিডিউর সেই প্রতিষ্ঠানের সম্পত্তি থাকে এবং অন্য কোনো প্রতিষ্ঠানের সাথে শেয়ার করা হয় না।</p><h2>প্রাপ্যতা</h2><p>একাডেমি সেবাটি নিরবচ্ছিন্নভাবে চালু রাখার লক্ষ্য রাখে, তবে বাধাহীন অ্যাক্সেসের নিশ্চয়তা দেয় না। পরিকল্পিত রক্ষণাবেক্ষণে অ্যাক্সেস বাধাগ্রস্ত হওয়ার আশঙ্কা থাকলে তা আগে থেকে ঘোষণা করা হয়।</p><h2>সম্পর্কিত পলিসি</h2><p>ব্যক্তিগত ডেটা কীভাবে পরিচালিত হয় তা <a href="/en/privacy">প্রাইভেসি পলিসিতে</a> বর্ণিত আছে।</p>',
