  'articles' => 
  array (
    'how-to-train-a-new-front-desk-agent' => 
    array (
      'title' => 'প্রথম দুই সপ্তাহে নতুন ফ্রন্ট ডেস্ক এজেন্টকে কীভাবে প্রশিক্ষণ দেবেন',
      'excerpt' => 'দুই সপ্তাহের একটি ক্রম, যা নতুন ফ্রন্ট অফিস এজেন্টকে তত্ত্বাবধান ছাড়া শিফটে কাজ করার পর্যায়ে নিয়ে যায়, হোটেলকে সুরক্ষা দেওয়া সেফটি ও প্রাইভেসি ট্রেনিং বাদ না দিয়েই।',
      'body' => '<p>নতুন ফ্রন্ট ডেস্ক এজেন্টকে সাধারণত খুব আগে বা খুব দেরিতে শিফটে দেওয়া হয়। খুব আগে দিলে তারা স্ট্যান্ডার্ড শেখার আগেই হোটেলের খারাপ অভ্যাস শিখে ফেলে। খুব দেরিতে দিলে তারা দায়িত্ব ছাড়া দুই সপ্তাহ শুধু পাশে থেকে দেখে, যা থেকে খুব কমই শেখা যায়। একটি নির্দিষ্ট দুই সপ্তাহের ক্রম দুটোই এড়ায়।</p><h2>প্রথম ও দ্বিতীয় দিন: ডেস্ক নয়, প্রপার্টি</h2><p>জরুরি নির্গমন পথ, সমবেত হওয়ার স্থান, তাদের ম্যানেজার কে, লকার কোথায় এবং রিপোর্টিং লাইন। ফায়ার সেফটি ও জরুরি প্রতিক্রিয়া প্রথম দিনেই সপ্তম দিনের শেষ তারিখসহ দেওয়া হয়, কারণ যে এজেন্ট একজন অতিথিকে সিঁড়ির দিকে দেখাতে পারে না, সে যত ভালোভাবেই চেক-ইন করুক, ঝুঁকি থেকেই যায়।</p><h2>তৃতীয় থেকে পঞ্চম দিন: ক্রম</h2><p>ফ্রন্ট অফিসের মৌলিক বিষয়, টেলিফোন শিষ্টাচার, তারপর চেক-ইন ও চেক-আউট আলাদা কোর্স হিসেবে। এজেন্ট একটি পূর্ণ আগমন-পর্ব ও একটি পূর্ণ প্রস্থান-পর্ব পাশে থেকে দেখে, এবং শুধু দেখার বদলে একজন অভিজ্ঞ এজেন্টের পাশাপাশি চেকলিস্ট চালায়।</p><h2>ষষ্ঠ থেকে অষ্টম দিন: সিস্টেম ও রেকর্ড</h2><p>প্রপার্টি ম্যানেজমেন্ট সিস্টেম ট্রেনিং, অতিথি রেজিস্ট্রেশন এবং অতিথির প্রাইভেসি। প্রাইভেসি পরে ভাবার বিষয় নয়: রুম নম্বরের শৃঙ্খলা, কলারকে কী জানানো যায় এবং পরিচয়পত্র কীভাবে সামলাতে হয়, এসবই এজেন্ট তত্ত্বাবধান ছাড়া সিস্টেমে প্রবেশাধিকার পাওয়ার আগে শেখে।</p><h2>নবম থেকে একাদশ দিন: তত্ত্বাবধানে</h2><p>এজেন্ট ডেস্কে কাজ করে, সুপারভাইজার উপস্থিত থাকেন কিন্তু প্রয়োজন না হলে হস্তক্ষেপ করেন না। প্রতিটি ব্যতিক্রম, প্রথম কঠিন অতিথি এবং প্রথম সিস্টেম ত্রুটি আরেকটি কোর্সের চেয়ে বেশি মূল্যবান।</p><h2>দ্বাদশ থেকে চতুর্দশ দিন: মূল্যায়ন ও ছাড়পত্র</h2><p>মূল্যায়নগুলো সম্পন্ন করুন, সুপারভাইজারের সাথে চেকলিস্টের ফলাফল পর্যালোচনা করুন এবং নিশ্চিত করুন যে বাধ্যতামূলক ট্রেনিং সম্পন্ন হিসেবে রেকর্ড হয়েছে। তত্ত্বাবধান ছাড়া শিফটে ছাড়া একটি সিদ্ধান্ত, যার সাথে একজনের নাম যুক্ত থাকে এবং যা কর্মীর নামে রেকর্ড হয়; যথেষ্ট সময় পার হয়েছে, এমন অনুমান নয়।</p><h2>এরপর কী</h2><p>দ্বিতীয় মাসে রুম অ্যাসাইনমেন্ট, অভিযোগ সামলানো ও আপসেলিং, এবং দিনের ক্রম স্বয়ংক্রিয় হয়ে গেলে তবেই নাইট অডিট।</p>',
    ),
    'writing-a-hotel-sop-people-actually-follow' => 
    array (
      'title' => 'এমন হোটেল SOP লেখা যা মানুষ সত্যিই মেনে চলে',
      'excerpt' => 'বেশিরভাগ হোটেল প্রসিডিউর একই চারটি কারণে ব্যর্থ হয়। প্রতিটিই ডকুমেন্ট প্রকাশের আগে ঠিক করা যায়।',
      'body' => '<p>বেশিরভাগ হোটেলের প্রসিডিউর আছে। কিন্তু এমন প্রসিডিউর অনেক কম, যা শিফটে যা ঘটে তা বদলে দেয়। ফাঁকটা প্রায় সবসময় লেখায়, টিমে নয়।</p><h2>এটি ধাপের বদলে ফলাফল বর্ণনা করে</h2><p>"নিশ্চিত করুন যে রুমটি প্রয়োজনীয় স্ট্যান্ডার্ড পূরণ করে" কোনো প্রসিডিউর নয়। "বাথরুম এই ক্রমে পরিষ্কার করুন: আয়না, বেসিন, বাথটাব বা শাওয়ার, টয়লেট সবশেষে, তারপর মেঝে" একটি প্রসিডিউর। কোনো বাক্য যদি সম্পাদন করা না যায়, তবে তা প্রসিডিউরে নয়, কোয়ালিটি স্ট্যান্ডার্ড অংশে থাকার কথা।</p><h2>এতে কোনো এসকেলেশন রুট নেই</h2><p>প্রতিটি প্রসিডিউর এমন পরিস্থিতির মুখোমুখি হয় যা আগে ভাবা হয়নি, সাধারণত সবচেয়ে খারাপ সময়ে। নির্দিষ্ট এসকেলেশন রুট ছাড়া প্রসিডিউর কর্মীকে নিজেই একটি রুট বানাতে বাধ্য করে, আর সেই বানানো রুট থেকেই ইনসিডেন্ট রিপোর্ট তৈরি হয়। কাকে ডাকা হবে, কীসের জন্য এবং কত জরুরিভাবে, তা লিখে দিন।</p><h2>কেউ বলতে পারে না তারা কোন সংস্করণ পড়েছে</h2><p>শেয়ার্ড ফোল্ডারে তারিখহীন প্রসিডিউর যাচাই করা যায় না। প্রতিটি প্রসিডিউরকে একটি সংস্করণ নম্বর, লেখক, অনুমোদনকারী, কার্যকর তারিখ ও পর্যালোচনার তারিখ দিন, পূর্ববর্তী সংস্করণগুলো পড়ার উপযোগী রাখুন এবং প্রতিটি নতুন সংস্করণ স্বীকার করতে বলুন। তাহলে অডিটের সময় একমাত্র গুরুত্বপূর্ণ প্রশ্নের উত্তর একজন ম্যানেজার দিতে পারবেন: কার্যকর সংস্করণটি কে পড়েছিল।</p><h2>এটি এমন কেউ লিখেছেন যিনি কাজটি করেন না</h2><p>অফিসে লিখে একটি বিভাগের হাতে দেওয়া প্রসিডিউরে সাধারণত এমন একটি ধাপ বাদ থাকে যা বিভাগটি এড়াতে পারে না। যারা কাজটি করেন তাদের সাথে খসড়া লিখুন, একবার তাদের সাথে ধাপে ধাপে চালিয়ে দেখুন, এবং প্রথম ব্যর্থতার পরে নয়, প্রকাশের আগেই সংশোধন করুন।</p><h2>প্রকাশের আগে একটি পরীক্ষা</h2><p>খসড়াটি এমন কাউকে দিন যিনি কখনো কাজটি করেননি, এবং হুবহু মেনে চলতে বলুন। তাদের প্রতিটি প্রশ্নই একটি বাদ পড়া ধাপ।</p>',
    ),
    'hotel-food-safety-records-that-survive-an-inspection' => 
    array (
      'title' => 'পরিদর্শনে টিকে থাকে এমন হোটেল ফুড সেফটি রেকর্ড',
      'excerpt' => 'একটি সম্পূর্ণ তাপমাত্রা লগ দেখতে কেমন, কেন ফাঁকা ঘর সবচেয়ে সাধারণ ফাইন্ডিং, এবং কাগজপত্রের বদলে কারণটি কীভাবে ঠিক করবেন।',
      'body' => '<p>একটি কিচেন সত্যিই নিরাপদ হয়েও রেকর্ডের কারণে ব্যর্থ হতে পারে। একজন পরিদর্শক নিরাপত্তার স্বাদ নিতে পারেন না, তাই লগই প্রমাণ, এবং অসম্পূর্ণ লগকে কাগজপত্রের অভাব নয়, নিয়ন্ত্রণের অভাব হিসেবে ধরা হয়।</p><h2>একটি সম্পূর্ণ লগে কী থাকে</h2><p>প্রতিটি শিফটের শুরুতে একটি ক্যালিব্রেশন এন্ট্রি। শীতল ও হিমায়িত সংরক্ষণ প্রতি শিফটে দুবার রেকর্ড। সার্ভিসের আগে রান্নার তাপমাত্রা নিশ্চিত। হট হোল্ডিং প্রতি দুই ঘণ্টায় রেকর্ড। ঠান্ডা করার সময় দুই ধাপের লক্ষ্যের বিপরীতে রেকর্ড। পুনরায় গরম করা একবার রেকর্ড। এবং সীমার বাইরের প্রতিটি রিডিংয়ের বিপরীতে নামসহ একটি সংশোধনমূলক পদক্ষেপ রেকর্ড।</p><h2>ঘরগুলো কেন ফাঁকা থাকে</h2><p>প্রায় কখনোই এজন্য নয় যে টিমের কোনো মাথাব্যথা নেই। সাধারণত কারণ হলো রিডিং নেওয়ার সময় শেফ যেখানে দাঁড়িয়ে থাকেন লগ সেখানে থাকে না, প্রোবটি শেয়ার করা এবং প্রয়োজনের মুহূর্তে পাওয়া যায় না, অথবা শিফট ব্যস্ত ছিল এবং পরে পূরণ করার ইচ্ছা ছিল। শিফটের শেষে স্মৃতি থেকে লেখা রেকর্ড নয়, এবং সাধারণত দেখেই তা বোঝা যায়।</p><h2>কারণটি ঠিক করা</h2><p>যেখানে রিডিং নেওয়া হয় লগ সেখানে রাখুন। প্রতিটি সেকশনকে নিজস্ব প্রোব দিন। দুই ঘণ্টা অন্তর হট হোল্ডিং চেককে শেয়ার্ড দায়িত্বের বদলে শিফট বোর্ডে একজন নির্দিষ্ট ব্যক্তির দায়িত্ব করুন। তারপর সাপ্তাহিকের বদলে প্রতিদিন লগ পরীক্ষা করুন, কারণ পরদিন সকালে পাওয়া ফাঁকের ব্যাখ্যা তখনও দেওয়া যায়।</p><h2>প্রশিক্ষণের মূল কথা</h2><p>লগ পূরণকে প্রশাসনিক কাজ নয়, দক্ষতার অংশ হিসেবে দেখুন। যে শেফকে শেখানো হয়েছে যে রেকর্ড নিয়ন্ত্রণেরই অংশ, তিনি রিডিং নেওয়ার মুহূর্তেই তা পূরণ করেন, আর কেবল সেই সময়ই তা সত্য।</p>',
    ),
    'measuring-hotel-training-completion-honestly' => 
    array (
      'title' => 'সততার সাথে হোটেল ট্রেনিং সম্পন্নের হার পরিমাপ',
      'excerpt' => 'কেন উপস্থিতি মানে সম্পন্ন নয়, কেন সম্পন্নের শতাংশ একমাত্র গুরুত্বপূর্ণ ফাঁকটি লুকিয়ে রাখতে পারে, এবং তার বদলে কী রিপোর্ট করবেন।',
      'body' => '<p>ট্রেনিং রিপোর্টকে ভালো দেখানো সহজ, কাজে লাগানো কঠিন। তিনটি অভ্যাসই বেশিরভাগ পার্থক্য তৈরি করে।</p><h2>উপস্থিতি মানে সম্পন্ন নয়</h2><p>স্বাক্ষরিত উপস্থিতি শিট রেকর্ড করে যে কেউ ঘরে ছিলেন। এটি রেকর্ড করে না যে তিনি কাজটি করতে পারেন। মূল্যায়নের ফলাফলের সাথে যুক্ত একটি সম্পন্নের রেকর্ড তা করে। দ্বিতীয়টি রিপোর্ট করুন, আর প্রথমটি কেবল সেখানে রাখুন যেখানে ক্লাসরুম সেশন সত্যিই প্রয়োজনীয়তার অংশ।</p><h2>গড় ফাঁকটি লুকিয়ে রাখে</h2><p>নব্বই শতাংশ সম্পন্নের একটি প্রপার্টি সুস্থ মনে হয়, যতক্ষণ না আপনি লক্ষ করেন যে বাকি দশ শতাংশ পুরো নাইট শিফট, অথবা গত মাসে যোগ দেওয়া প্রত্যেক নতুন কর্মী। বিভাগ, প্রপার্টি ও ব্যক্তি অনুযায়ী রিপোর্ট করুন, এবং ওভারডিউ তালিকা শতাংশের ওপরে রাখুন, কারণ তালিকার ওপরই কেউ পদক্ষেপ নিতে পারে।</p><h2>হালনাগাদ না থাকলে সম্পন্ন মানে কমপ্লায়েন্স নয়</h2><p>সেফটি ও ফুড সেফটি ট্রেনিংয়ের মেয়াদ শেষ হয়। যে রিপোর্ট মেয়াদোত্তীর্ণ সার্টিফিকেটকে সম্পন্ন হিসেবে গোনে, তা রিপোর্ট না থাকার চেয়েও খারাপ, কারণ এটি অযৌক্তিক আস্থা তৈরি করে। মেয়াদ শেষের কাছাকাছি সার্টিফিকেটগুলো ব্যতিক্রম রিপোর্ট হিসেবে নয়, স্থায়ী আইটেম হিসেবে দেখান।</p><h2>একজন ম্যানেজারের সামনে কী রাখবেন</h2><p>চারটি বিষয়: এখন কে ওভারডিউ, এই সপ্তাহে কে ওভারডিউ হবে, এই মাসে কোন সার্টিফিকেটের মেয়াদ শেষ হবে, এবং কোন প্রসিডিউরের বর্তমান সংস্করণ স্বীকার করা হয়নি। বাকি সবকিছু প্রেক্ষাপট।</p>',
    ),
    'training-hotel-teams-in-arabic-and-english' => 
    array (
      'title' => 'কোনোটি না হারিয়ে আরবি ও ইংরেজিতে হোটেল টিমকে প্রশিক্ষণ',
      'excerpt' => 'কেন অনূদিত কোর্স মানে দ্বিভাষিক কোর্স নয়, এবং বাস্তবে একটি সত্যিকারের দ্বিভাষিক হোটেল ট্রেনিং প্রোগ্রাম দেখতে কেমন।',
      'body' => '<p>সৌদি আরবের বেশিরভাগ হোটেল টিম সত্যিই দ্বিভাষিক, তবে সমানভাবে নয়। একটি হাউসকিপিং ফ্লোর মূলত আরবিতে কাজ করতে পারে, ফ্রন্ট ডেস্ক মূলত ইংরেজিতে, আর কিচেন এমন মিশ্রণে যা শিফট অনুযায়ী বদলায়। যে ট্রেনিং প্রোগ্রাম একটি ভাষা বেছে নেয়, সেটি নীরবে টিমের একটি অংশকে বাদ দেয়।</p><h2>অনুবাদ আর মূল লেখা এক নয়</h2><p>মেশিনে অনূদিত কোর্স পড়লেই অনূদিত মনে হয়, আর যে প্রসিডিউরাল নির্দেশনা আড়ষ্টভাবে পড়া যায় তা চাপের মধ্যে ভুল বোঝা হয়। আরবি সংস্করণটি আরবি কনটেন্ট হিসেবে লিখুন, বিভাগ শিফটে যে পরিভাষা আসলে ব্যবহার করে তা দিয়ে, এবং ইংরেজি সংস্করণটি ইংরেজি কনটেন্ট হিসেবে। এদের অর্থে সামঞ্জস্য রাখুন, শব্দে শব্দে নয়।</p><h2>ডান থেকে বাম একটি লেআউট, শুধু লেখার দিক নয়</h2><p>আরবি পেজ মানে লেখা উল্টে দেওয়া ইংরেজি পেজ নয়। নেভিগেশন, অগ্রগতির সূচক, চেকলিস্ট, টেবিল এবং ফর্মের ঘর সবকিছুই স্বাভাবিকভাবে ডান দিক থেকে পড়তে হবে। আরবি ইন্টারফেসে বাম থেকে ডানে চলা একটি সংখ্যাযুক্ত প্রসিডিউরে মানুষ ধাপের ক্রম ভুল পড়বে।</p><h2>প্রতি সেশনে শিক্ষার্থীকে বেছে নিতে দিন</h2><p>ভাষা প্রতি সেশনের পছন্দ হওয়া উচিত, সাইন-আপের সময় একবার ঠিক করা অ্যাকাউন্ট সেটিং নয়। একজন শিক্ষার্থী সেফটি কোর্স আরবিতে এবং প্রপার্টি ম্যানেজমেন্ট সিস্টেম কোর্স ইংরেজিতে নিতে পারেন, কারণ সিস্টেমটিই ইংরেজিতে। ভাষা বদলালেও অগ্রগতি বজায় থাকতে হবে।</p><h2>যে পরিভাষা অনুবাদ করা উচিত নয়</h2><p>সিস্টেমের ফিল্ডের নাম, রেডিওতে ব্যবহৃত কোড শব্দ এবং যন্ত্রপাতিতে ছাপা যেকোনো পরিভাষা কাজে যে ভাষায় দেখা যায় সেই ভাষাতেই রাখা উচিত, ব্যাখ্যা থাকবে শিক্ষার্থীর ভাষায়। শিক্ষার্থী যে বাটনের লেবেল স্ক্রিনে ইংরেজিতে দেখবেন তা অনুবাদ করলে ফাঁক বন্ধ হয় না, বরং তৈরি হয়।</p>',
    ),
    'pre-opening-hotel-training-checklist' => 
    array (
      'title' => 'প্রি-ওপেনিং হোটেল ট্রেনিং: প্রথম অতিথির আগে যা করতেই হবে',
      'excerpt' => 'যে ট্রেনিং ও প্রসিডিউরের কাজ একটি প্রি-ওপেনিং টিম পিছিয়ে দিতে পারে না, কখন তা করতে হবে সেই ক্রমে সাজানো।',
      'body' => '<p>প্রি-ওপেনিং এক বছরের অপারেশনাল প্রস্তুতিকে কয়েক মাসে সংকুচিত করে, আর ট্রেনিং সাধারণত সেই অংশ যা পিছিয়ে যায়, কারণ ভবনের তুলনায় এটি কম জরুরি মনে হয়। আসলে তা নয়, কারণ ওপেনিংয়ের তারিখ সরে না, কিন্তু টিমের প্রস্তুতি সরে যায়।</p><h2>নব্বই দিন আগে: প্রসিডিউর</h2><p>যারা প্রসিডিউর মেনে চলবেন তাদের নিয়োগের আগেই প্রসিডিউরগুলো লিখুন। যে বিভাগ এসে কোনো লিখিত স্ট্যান্ডার্ড পায় না, সে নিজেই একটি বানিয়ে নেয়, আর পরে সেই বানানো স্ট্যান্ডার্ড বদলাতে এখন লেখার চেয়ে বেশি খরচ হয়। শুরু থেকেই প্রতিটি প্রসিডিউরের একজন মালিক, একজন অনুমোদনকারী এবং একটি পর্যালোচনার তারিখ দরকার।</p><h2>ষাট দিন আগে: বাধ্যতামূলক সেট</h2><p>ফায়ার সেফটি, জরুরি প্রতিক্রিয়া এবং প্রপার্টি ইনডাকশন প্রত্যেক কর্মীকে দেওয়া হয়, যার শেষ তারিখ গ্র্যান্ড ওপেনিং নয়, সফট ওপেনিংয়ের আগে। হাউসকিপিং কোনো পণ্য ছোঁয়ার আগে কেমিক্যাল সেফটি। কিচেন টেস্ট সার্ভিস চালানোর আগে ফুড সেফটি।</p><h2>ত্রিশ দিন আগে: বিভাগীয় ক্রম</h2><p>প্রতিটি বিভাগ তার মূল ক্রম সম্পন্ন করে এবং ট্রেনিং রুমে নয়, আসল ফ্লোরে তার চেকলিস্ট চালায়। প্রথম অতিথির আগে একটি হাউসকিপিং টিমের উচিত প্রকৃত ভবনের আসল রুম পরিষ্কার করা, যে রুমগুলো এখনো শেষ হয়নি সেগুলোসহ।</p><h2>চৌদ্দ দিন আগে: মহড়া</h2><p>কর্মীদের অতিথি সাজিয়ে একটি পূর্ণ সিমুলেটেড দিন চালান: আগমন, একটি রেস্তোরাঁ সার্ভিস, একটি অভিযোগ, একটি রক্ষণাবেক্ষণ কল এবং একটি ইভাকুয়েশন ড্রিল। এটি যে প্রতিটি ফাঁক প্রকাশ করে, তা না হলে একজন অতিথি খুঁজে পেতেন।</p><h2>রিলিজের আগে</h2><p>ওপেনিংয়ের তারিখ যা-ই হোক, অমীমাংসিত ফায়ার সেফটি, বৈদ্যুতিক বা পানি নিরাপত্তার কোনো আইটেম থাকলে কোনো রুম বিক্রির জন্য ছাড়া হয় না। এই সিদ্ধান্ত একবারই, লিখিতভাবে, চাপ আসার আগেই নিতে হবে।</p>',
    ),
