      'answer' => 'ফায়ার সেফটি, জরুরি প্রতিক্রিয়া এবং প্রপার্টি ইনডাকশন বিভাগ নির্বিশেষে প্রত্যেক কর্মীকে দেওয়া হয়, সাধারণত যোগদানের তারিখ থেকে সাত দিনের সময়সীমাসহ। কেমিক্যাল সেফটি, ফুড সেফটি এবং ছুরি ব্যবহারের নিরাপত্তা সেই ভূমিকাগুলোর জন্য বাধ্যতামূলক যারা এই ঝুঁকিগুলো সামলায়।',
